-- 2. TODA membership masterlist — 817 anonymised members
--    No names, addresses or contact details: membership statistics only.
-- ---------------------------------------------------------------------------
with counts as (
  select * from (values
    ('TODA-001', 63),
    ('TODA-002', 57),
    ('TODA-003', 54),
    ('TODA-004', 50),
    ('TODA-005', 46),
    ('TODA-006', 43),
    ('TODA-007', 41),
    ('TODA-008', 39),
    ('TODA-009', 37),
    ('TODA-010', 35),
    ('TODA-011', 33),
    ('TODA-012', 31),
    ('TODA-013', 30),
    ('TODA-014', 28),
    ('TODA-015', 28),
    ('TODA-016', 26),
    ('TODA-017', 26),
    ('TODA-018', 24),
    ('TODA-019', 24),
    ('TODA-020', 22),
    ('TODA-021', 22),
    ('TODA-022', 20),
    ('TODA-023', 20),
    ('TODA-024', 18)
  ) as t(code, member_count)
)
insert into public.toda_members (toda_id, member_ref, display_name, year_joined, is_active)
select t.id,
       t.code || '-M' || lpad(gs.n::text, 4, '0'),
       'Member ' || lpad(gs.n::text, 4, '0'),
       -- Deterministic spread of join years between 1998 and 2025
       (1998 + ((gs.n * 7 + length(t.code)) % 28))::smallint,
       (gs.n % 17 <> 0)  -- roughly 6% inactive roster entries
  from counts c
  join public.todas t on t.code = c.code
  cross join lateral generate_series(1, c.member_count) as gs(n)
on conflict (member_ref) do nothing;

-- ---------------------------------------------------------------------------
-- 3. Demonstration accounts
--    administrator : 1 account
--    staff         : 3 accounts
--    driver        : 72 accounts (three per TODA, linked to the roster)
--    Passwords are demonstration values and must be changed in any real
--    deployment (they are documented in docs/deployment.md).
-- ---------------------------------------------------------------------------
do $$
declare
  v_id uuid;
  r    record;
begin
  perform public.seed_create_auth_user(
    'admin@mabini-sbtf.test', 'Admin@Mabini2026', 'administrator',
    'Apolinaria', 'Reyes', 'Domingo', '09171234501', '041016017',
    'Municipal Hall, Poblacion, Mabini, Batangas', now() - interval '400 days');

  perform public.seed_create_auth_user(
    'staff1@mabini-sbtf.test', 'Staff@Mabini2026', 'staff',
    'Benigno', 'Cruz', 'Magsaysay', '09171234502', '041016017',
    'Sangguniang Bayan Office, Poblacion, Mabini, Batangas', now() - interval '380 days');

  perform public.seed_create_auth_user(
    'staff2@mabini-sbtf.test', 'Staff@Mabini2026', 'staff',
    'Corazon', 'Lim', 'Villamor', '09171234503', '041016017',
    'Sangguniang Bayan Office, Poblacion, Mabini, Batangas', now() - interval '300 days');

  perform public.seed_create_auth_user(
    'staff3@mabini-sbtf.test', 'Staff@Mabini2026', 'staff',
    'Diosdado', 'Ybañez', 'Panganiban', '09171234504', '041016009',
    'Sangguniang Bayan Office, Poblacion, Mabini, Batangas', now() - interval '120 days');

  -- Driver accounts: two to three per TODA so every dashboard segment has data.
  for r in
    select t.code, t.barangay_code, row_number() over (order by t.code) as toda_rank
      from public.todas t
  loop
    for i in 1..3 loop
      v_id := public.seed_create_auth_user(
        'driver' || lpad((r.toda_rank * 10 + i)::text, 3, '0') || '@mabini-sbtf.test',
        'Driver@Mabini2026', 'driver',
        (array['Adrian','Alvin','Arnel','Benjamin','Carlito','Danilo','Dennis','Edgar','Efren','Elmer','Ernesto','Ferdinand','Gilbert','Gregorio','Henry','Isagani','Jaime','Joel','Jonathan','Jose','Julio','Leonardo','Lorenzo','Manuel','Marcelo','Mario','Marvin','Melchor','Michael','Nestor','Noel','Oliver','Orlando','Oscar','Pablo','Pedro','Rafael','Ramil','Ramon','Raul','Renato','Ricardo','Roberto','Rodolfo','Rogelio','Rolando','Romeo','Ronald','Ruben','Salvador','Samuel','Teodoro','Vincent','Virgilio','Wilfredo','Wilson','Antonio','Cesar','Dominador','Emmanuel'])[(r.toda_rank * 3 + i) % 60 + 1],
        (array['Abad','Aguilar','Alcantara','Alvarez','Angeles','Aquino','Bautista','Bernardo','Cabrera','Castro','Cortez','Cruz','Diaz','Domingo','Enriquez','Espino','Estrada','Fernandez','Flores','Francisco','Garcia','Gonzales','Hernandez','Jimenez','Lopez','Mendoza','Mercado','Navarro','Ocampo','Ortiz','Padilla','Pascual','Perez','Ramos','Reyes','Rivera','Rodriguez','Rosales','Salazar','Santiago','Santos','Tolentino','Torres','Valdez','Villanueva','Zamora','Marasigan','Manalo','Malabanan','Macatangay'])[(r.toda_rank * 3 + i) % 50 + 1],
        (array['Abanto','Agbayani','Almario','Atienza','Balbuena','Banaag','Bautista','Briones','Buenaventura','Cabrera','Cantos','Claveria','Contreras','Dalisay','De Guzman','Dimaculangan','Dimaano','Ebora','Fajardo','Feliciano','Garcia','Gonzales','Guevarra','Hernandez','Javier','Landicho','Lipa','Malabanan','Mendoza','Miranda','Nolasco','Ocampo','Olivares','Ortega','Panganiban','Pastor','Perez','Quinto','Ramos','Ramoso','Rico','Rivera','Salazar','Sandoval','Sarmiento','Silang','Sison','Tenorio','Tolentino','Umali','Valencia','Vasquez','Villamor','Yabut','Zamora'])[(r.toda_rank * 3 + i) % 55 + 1],
        '0918' || lpad(((r.toda_rank * 37 + i * 7) % 10000000)::text, 7, '0'),
        r.barangay_code,
        'Purok ' || (1 + (r.toda_rank % 5)) || ', ' || r.code,
        now() - ((r.toda_rank * 3 + i) * 7 + 20) * interval '1 day');
    end loop;
  end loop;

  -- Link roster entries to the registered accounts of their TODA.
  with ranked as (
    select m.id,
           row_number() over (partition by m.toda_id order by m.member_ref) as rn
      from public.toda_members m
  )
  update public.toda_members m
     set profile_id = d.id
    from ranked r
    join public.profiles d
      on d.role = 'driver'
     and d.toda_id = (select toda_id from public.toda_members where id = r.id)
     and d.email like 'driver%'
   where m.id = r.id and r.rn <= 3;
end
$$;

